import {getIssueActionPlan} from './issue-actions.js';
import {decorateIssueAnswer} from './issue-action-ui.js';
import {setupChat} from './chat.js';
import {setupCodeLibrary} from './library-ui.js';
import { BASELINE, PROPOSED, evaluateDesign, SCREENING_NOTE, SOURCE_URL } from './rules.js';
import {toLocal,toGeo,inPolygon,footprint,polygonArea,screenToGeo,overlaySVG,polygonContainsPolygon,isSimplePolygon} from './parcel.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const paths={play:'m9 5 10 7-10 7Z',download:'M12 3v12m-5-5 5 5 5-5M5 16v5h14v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4',box:'m12 3 9 5v9l-9 5-9-5V8l9-5Zm0 9 9-4M3 8l9 4m0 0v10M7.5 5.5l9 5',sliders:'M4 6h6m4 0h6M4 12h10m4 0h2M4 18h2m4 0h10M10 3v6m4 0v6M6 15v6',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Zm6-2v16m6-14v16',expand:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5',scan:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M7 12h10m-5-5v10',move:'M12 3v18M3 12h18M8 7l4-4 4 4M8 17l4 4 4-4M7 8l-4 4 4 4m10-8 4 4-4 4',reset:'M3 11a9 9 0 1 1 2 7M3 4v7h7',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3ZM20 2v4m-2-2h4',link:'m10 13 4-4M8 16l-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m0 11a4 4 0 0 0 6 0l5-5a4 4 0 0 0-6-6l-1 1',info:'M12 11v6m0-10v.1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',focus:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0'};
$$('[data-icon]').forEach(el=>{el.innerHTML=`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[el.dataset.icon]||paths.info}"/></svg>`;});
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let caseMode='office',gardenReview=null;
let input={...BASELINE},results=evaluateDesign(input),selected='width',scenario='before',viewer=null,imported=false,context=null,connections=null,move=false;
let site={lat:1.2996,lng:103.7875,name:'One-north, Singapore'},pendingSite={...site},placement={x:0,z:0,rotation:0};
const defaultParcel=anchor=>[[-44,-35],[44,-35],[44,35],[-44,35]].map(([x,z])=>toGeo({x,z},anchor));
let parcel=defaultParcel(site),pendingParcel=[],pendingPlacement={...placement},mapMode='site',modelDimensions={x:38,z:26};
function hasSavedDraft(){try{return !!localStorage.getItem('firesite-parcel-v1');}catch{return false;}}
function saveDraft(){try{localStorage.setItem('firesite-parcel-v1',JSON.stringify({site,parcel,placement}));}catch{}}
function restoreDraft(){try{const d=JSON.parse(localStorage.getItem('firesite-parcel-v1'));if(!d||!Number.isFinite(d.site?.lat)||!Number.isFinite(d.site?.lng)||Math.abs(d.site.lat)>85||Math.abs(d.site.lng)>180||!Array.isArray(d.parcel)||d.parcel.length>12||!isSimplePolygon(d.parcel.map(p=>toLocal(p,d.site))))return;if(!['x','z','rotation'].every(k=>Number.isFinite(d.placement?.[k])))return;site=d.site;parcel=d.parcel;placement=d.placement;$('#siteName').textContent=String(site.name).slice(0,100);$('#rotation').value=placement.rotation;$('#rotationOut').textContent=placement.rotation+'°';}catch{}}
function drawParcel(){const points=parcel.map(p=>toLocal(p,site));viewer?.setParcel(points);$('#miniParcel').innerHTML=overlaySVG(parcel,placement,site,site,modelDimensions);const fits=polygonContainsPolygon(footprint(placement,modelDimensions.x,modelDimensions.z),points);$('#placeHint').innerHTML=`${fits?'Footprint within drawn parcel.':'Footprint extends outside drawn parcel.'}<br>${fits?'建筑轮廓位于示意地块内。':'建筑轮廓超出示意地块。'} · ${placement.rotation}°`;}
function drawPending(){const points=pendingParcel.map(p=>toLocal(p,pendingSite));const area=polygonArea(points);const fits=points.length>=3&&polygonContainsPolygon(footprint(pendingPlacement,modelDimensions.x,modelDimensions.z),points);$('#parcelOverlay').innerHTML=overlaySVG(pendingParcel,pendingPlacement,pendingSite,pendingSite,modelDimensions);$('#parcelStats').innerHTML=`${pendingParcel.length} vertices / 个顶点 · ${Math.round(area).toLocaleString()} m² · ${fits?'Building inside / 建筑在地块内':'Check footprint / 检查建筑边界'}`;$('#siteRotation').value=pendingPlacement.rotation;$('#siteRotationOut').textContent=pendingPlacement.rotation+'°';}
function setMapMode(mode){mapMode=mode;$$('[data-map-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mapMode===mode));$('#parcelHelp').textContent=mode==='plot'?'Click 3+ corners to draw the boundary. / 点击至少 3 个角点圈选边界。':mode==='building'?'Click inside the parcel to position your building. / 点击地块内部放置建筑。':'Click the map to change the site anchor. / 点击地图更换场地定位。';}
let toastTimer,selectedCode=null;
setupChat({getContext:()=>({findings:results,project:{model:$('#modelName').textContent,selectedFindingId:selected,purposeGroup:input.purposeGroup,inputSource:input.source,site,selectedCode}}),onOpenCodes:()=>$('#libraryBtn').click(),onFocusIssue:focusModelIssue});
setupCodeLibrary({getViewer:()=>viewer,onSelectCode:(code,outcome)=>{selectedCode=code;$('#selectedCodeTray').hidden=false;$('#selectedCodeTitle').textContent=code.clause+' · '+code.title.en;$('#selectedCodeState').textContent=outcome?.located?'Region linked · review required / 已关联区域，待核实':'Location needs evidence / 待提供模型定位依据';},onAskAI:()=>$('#aiBtn').click(),notify:toast});
$('#clearCodeBtn').onclick=()=>{selectedCode=null;viewer?.clearCodeMark();$('#selectedCodeTray').hidden=true;};
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
function info(title,html,kicker='SITECODE AI'){ $('#infoTitle').textContent=title;$('#infoEyebrow').textContent=kicker;$('#infoBody').innerHTML=html;if(!$('#infoDialog').open)$('#infoDialog').showModal();}
$$('.close-dialog').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
function render(){
 results=caseMode==='garden'&&gardenReview?gardenReview.findings:evaluateDesign(input); const fail=results.filter(x=>x.status==='fail').length,review=results.filter(x=>x.status==='review').length,pass=results.filter(x=>x.status==='pass').length;
 const good=fail===0&&review===0;
 $('#reviewSummary').className='review-summary'+(good?' good':'');
 $('#reviewSummary').innerHTML=`<span class="summary-number">${fail||review||pass}</span><div class="summary-copy"><strong>${fail?'design issues to resolve':review?'checks need evidence':'selected criteria met'}</strong><small>${fail?'项设计问题待调整':review?'项检查待补充证据':'项所选指标满足输入阈值'} · ${caseMode==='garden'?'模型参数':input.source==='demo'?'示例参数':'申报参数'}</small><div class="summary-meter">${results.map(r=>`<i class="${r.status}"></i>`).join('')}</div></div>`;
 $('#findingsList').innerHTML=results.map((r,i)=>`<button class="finding ${r.status} ${selected===r.id?'selected':''}" data-finding="${r.id}" aria-pressed="${selected===r.id}"><span class="finding-index">${r.status==='pass'?'✓':String(i+1).padStart(2,'0')}</span><span class="finding-info"><strong>${escape(caseMode==='garden'?['Approach road width','Pergola clearance','Accessway width','Pool review zone'][i]:r.title.en)}</strong><small>${escape(caseMode==='garden'?['入口车道净宽','入口廊架净空','消防作业场地净宽','泳池与复核区'][i]:r.title.zh)}</small></span><span class="finding-value"><b>${escape(caseMode==='garden'?String(r.value)+' '+r.unit:r.measured.en)}</b><small>${r.status==='fail'?'ADJUST / 调整':r.status==='pass'?'MEETS / 满足':r.status==='na'?'N/A / 不适用':'REVIEW / 待核实'}</small></span></button>`).join('');
 $$('[data-finding]').forEach(b=>b.addEventListener('click',()=>select(b.dataset.finding)));
 const r=results.find(x=>x.id===selected)||results[0];
 $('#findingDetail').innerHTML=`<div class="detail-kicker"><span>CODE → DESIGN / 条款到设计</span><a href="${SOURCE_URL}" target="_blank" rel="noopener">§${escape(r.clause.replace(/^SCDF Fire Code 2023,?\s*/,""))} ↗</a></div><h3>${escape(r.requirement.en)}<small>${escape(r.requirement.zh)}</small></h3><p>${escape(r.explanation.en)}<small>${escape(r.explanation.zh)}</small></p><div class="detail-recommendation"><span>DESIGN ACTION / 调整建议</span><p>${escape(r.recommendation.en)}<small>${escape(r.recommendation.zh)}</small></p></div><div class="detail-evidence">${escape(r.evidence.en)} · ${escape(r.evidence.zh)} · SCDF source checked 31 Oct 2026</div>`;
 $('#beforeBtn').classList.toggle('active',scenario==='before');$('#afterBtn').classList.toggle('active',scenario==='after');
 $('#applyBtn').innerHTML=scenario==='after'?'<span>↺</span><span>Return to original<small>回到原始方案</small></span>':'<span>✧</span><span>Apply proposed changes<small>应用示例调整并复查</small></span><span>→</span>';
 $('#applyBtn').disabled=imported;$('#afterBtn').disabled=imported;$('#beforeBtn').disabled=imported;
 if(caseMode==='garden'){viewer?.setExternalIssues?.(results);viewer?.selectExternalIssue?.(selected);$('#beforeBtn').disabled=false;$('#afterBtn').disabled=false;$('#beforeBtn').innerHTML='Original model <small>原始模型</small>';$('#afterBtn').innerHTML='Review locations <small>问题定位</small>';$('#applyBtn').disabled=false;$('#applyBtn').innerHTML='<span>✧</span><span>Generate improvement brief<small>生成模型改进建议</small></span><span>→</span>';}else{viewer?.setDesign(input);viewer?.setIssues(results);viewer?.selectIssue(selected);}$('.findings-heading>span:last-child').textContent=results.length+' CHECKS';
}
function select(id){if($('#modelActionPanel')?.dataset.issueId!==id)$('#modelActionPanel')?.setAttribute('hidden','');selected=id;render();}
function focusModelIssue(id,objectId){
 const finding=results.find(r=>r.id===id);if(!finding||!viewer||!finding.objectId||(objectId&&objectId!==finding.objectId)){toast('No confirmed model object for this issue. / 此问题尚未关联可靠的模型对象。');return {located:false};}
 selected=id;render();const result=viewer.focusExternalIssue?.(id);if(!result?.located){toast('Model object could not be located. / 未能定位该模型对象。');return {located:false};}
 $('#chatPanel').hidden=true;$('#chatLauncher').setAttribute('aria-expanded','false');if($('#infoDialog').open)$('#infoDialog').close();
 $('#perspectiveBtn').classList.add('active');$('#topBtn').classList.remove('active');
 let panel=$('#modelActionPanel');if(!panel){panel=document.createElement('section');panel.id='modelActionPanel';panel.className='model-action-panel';panel.tabIndex=-1;panel.setAttribute('aria-live','polite');$('.design-bottom').before(panel);}
 const plan=getIssueActionPlan(finding);panel.hidden=false;panel.dataset.issueId=id;panel.dataset.objectId=result.objectId;
 panel.innerHTML=`<div class="model-action-heading"><span>${plan.reviewOnly?'REVIEW LOCATION / 复核位置':'DESIGN ACTION / 修改建议'} · ${escape(id)}</span><button class="icon-btn" id="closeModelAction" aria-label="Close advice / 关闭建议">×</button></div><h3>${escape(finding.title.zh)}<small>${escape(finding.title.en)}</small></h3><div class="model-action-values"><div><small>当前 / Current</small><strong>${escape(plan.current.zh||plan.current.en)}</strong></div><span>→</span><div><small>${plan.reviewOnly?'复核条件 / Review':'建议目标 / Target'}</small><strong>${escape(plan.target.zh||plan.target.en)}</strong></div></div>${plan.delta?`<div class="model-action-delta">${escape(plan.delta.zh||plan.delta.en)}</div>`:''}<p>${escape(plan.action.zh)}<small>${escape(plan.action.en)}</small></p><div class="model-action-footer"><button id="returnToChat">← 返回 AI 对话 / Back to chat</button><button id="modelOverview">模型总览 / Overview ↗</button></div>`;
 panel.scrollTop=0;$('#closeModelAction').onclick=()=>{panel.hidden=true;};$('#returnToChat').onclick=()=>$('#chatLauncher').click();$('#modelOverview').onclick=()=>{viewer.resetCamera();panel.hidden=true;};
 $('#sceneWrap').scrollIntoView({behavior:'smooth',block:'center'});panel.focus({preventScroll:true});return result;
}
function setScenario(which){if(caseMode==='garden'){if(which==='before')viewer?.resetCamera();else select(gardenReview.findings[0].id);return;}if(imported)return;scenario=which;input={...(which==='after'?PROPOSED:BASELINE)};render();$('#provenanceText').innerHTML='Model geometry + declared design values<small>当前检查采用示例参数；场地影像与周边地点由 Google API 提供。</small>';}
$('#beforeBtn').onclick=()=>setScenario('before');$('#afterBtn').onclick=()=>setScenario('after');$('#applyBtn').onclick=()=>{if(caseMode==='garden'){$('#aiBtn').click();return;}setScenario(scenario==='after'?'before':'after');toast(scenario==='after'?'Updated: five selected criteria meet the declared thresholds. / 已更新：五项示例指标满足输入阈值。':'Original design restored / 已恢复原始示例方案');};
$('#rerunBtn').onclick=()=>{render();toast('Five checks recalculated from current inputs. / 已依据当前输入重新计算五项指标。');};
function openParams(){if(caseMode==='garden'){info('Model evidence / 模型参数依据',`<p>Canopy Garden Residences · PG II · 20 storeys<br><small>模型声明为虚构的缺陷方案；居住高度 61.145 m 为模型构造值。</small></p>${gardenReview.findings.map(r=>`<div class="info-row"><b>${escape(r.title.en)} / ${escape(r.title.zh)}</b><p>${escape(r.measured.en)}<br><small>${escape(r.evidence.en)}<br>${escape(r.evidence.zh)}</small></p></div>`).join('')}`,'SOURCE RHINO MODEL · 本地模型');return;}const form=$('#paramsForm');form.reset();for(const [k,v]of Object.entries(input)){if(form.elements[k])form.elements[k].value=v===null?'unknown':String(v);}$('#confirmInputs').checked=false;$('#paramsDialog').showModal();}
$('#parametersBtn').onclick=openParams;
$('#paramsForm').onsubmit=e=>{e.preventDefault();const data=new FormData(e.currentTarget);const updated={...input,source:'user',turningVerified:false};for(const[k,v]of data){updated[k]=['turningFacility','hasOverhead'].includes(k)?v==='unknown'?null:v==='true':Number(v);}input=updated;scenario='custom';render();$('#paramsDialog').close();$('#provenanceText').innerHTML='Checks use user-declared design values<small>当前结果依据手动申报参数；尚未从模型或地图自动测量。</small>';toast('Inputs saved and checks rerun / 已保存参数并复查');};

function updatePosition(){viewer?.setTransform(placement);const lat=site.lat-placement.z/111320,lng=site.lng+placement.x/(111320*Math.cos(site.lat*Math.PI/180));$('#coords').textContent=`${lat.toFixed(5)}° N, ${lng.toFixed(5)}° E`;drawParcel();saveDraft();}
$('#rotation').oninput=e=>{placement.rotation=Number(e.target.value);$('#rotationOut').textContent=placement.rotation+'°';updatePosition();};
$('#moveBtn').onclick=()=>{move=!move;viewer?.setMoveMode(move);$('#moveBtn').classList.toggle('active',move);$('#placeHint').innerHTML=move?'Click the ground to position the model.<br>点击场地地面放置模型。':'Rotate the view to inspect the site.<br>拖动旋转视角，滚轮缩放。';};
$('#resetPos').onclick=()=>{placement={x:0,z:0,rotation:0};$('#rotation').value=0;$('#rotationOut').textContent='0°';updatePosition();};
$('#recenterBtn').onclick=()=>viewer?.resetCamera();
$('#perspectiveBtn').onclick=()=>{viewer?.setView('perspective');$('#perspectiveBtn').classList.add('active');$('#topBtn').classList.remove('active');};$('#topBtn').onclick=()=>{viewer?.setView('top');$('#topBtn').classList.add('active');$('#perspectiveBtn').classList.remove('active');};
async function useSample(){if(gardenReview){await loadGardenCase();return;}viewer?.useSample();imported=false;modelDimensions={x:38,z:26};$('#modelFile').value='';$('#modelName').textContent='One North Office';$('#modelSub').textContent='Built-in sample · 内置示例模型';$('#modelType').textContent='PG IV · Office / 办公';$('#sceneCaption').innerHTML='SAMPLE GEOMETRY <small>示例几何 · 环境示意</small>';$('#sceneInstruction').innerHTML='Drag to orbit · Scroll to zoom <span>拖动旋转 · 滚轮缩放</span>';setScenario('before');$('#resetPos').click();}
$('#sampleBtn').onclick=useSample;
$('#modelFile').addEventListener('change',()=>$('#modelActionPanel')?.remove());
$('#modelFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!viewer){toast('3D viewer unavailable; reload this page. / 三维视图不可用，请刷新。');return;}if(file.size>50*1024*1024){toast('Please use a model smaller than 50 MB. / 请使用小于 50 MB 的模型。');return;}$('#sceneLoading').hidden=false;$('#sceneLoading strong').textContent='Importing your model';try{const meta=await viewer.loadFile(file,{units:$('#units').value});caseMode='imported';imported=true;modelDimensions={x:meta.bounds.x,z:meta.bounds.z};drawParcel();scenario='custom';input={purposeGroup:'IV',habitableHeight:null,accessType:'road',source:'unknown',hasOverhead:null,turningFacility:null};render();$('#modelName').textContent=file.name;$('#modelSub').textContent=`${meta.objects??'—'} objects · 几何导入完成`;$('#modelType').textContent='Parameters needed / 需填写参数';$('#sceneCaption').innerHTML='IMPORTED GEOMETRY <small>外部模型 · 无自动尺寸判断</small>';$('#sceneInstruction').innerHTML='Model imported · issue locations need mapping <span>模型已导入 · 问题定位待关联</span>';$('#provenanceText').innerHTML='Imported geometry; design inputs required<small>未从几何推断消防参数；请点击「查看参数」补充测量值。</small>';toast('Model imported. Add measured inputs to run checks. / 模型已导入，请补充测量参数。');}catch(err){toast('Import failed: '+String(err.message).slice(0,130));}finally{$('#sceneLoading').hidden=true;$('#sceneLoading strong').textContent='Building your workspace';}};

function mapUrl(s,zoom=19){return `/api/map?lat=${encodeURIComponent(s.lat)}&lng=${encodeURIComponent(s.lng)}&zoom=${zoom}`;}
function loadMiniMap(){const image=$('#miniMap');image.onload=()=>{image.hidden=false;$('.map-placeholder').hidden=true;};image.onerror=()=>{image.hidden=true;$('.map-placeholder').hidden=false;};image.src=mapUrl(site);}
function pendingMap(){ $('#latitude').value=pendingSite.lat.toFixed(6);$('#longitude').value=pendingSite.lng.toFixed(6);$('#largeMap').src=mapUrl(pendingSite);drawPending();}
function openSite(){pendingSite={...site};pendingParcel=parcel.map(p=>({...p}));pendingPlacement={...placement};setMapMode('site');pendingMap();$('#siteDialog').showModal();}
$('#siteBtn').onclick=openSite;$('#editSite').onclick=openSite;
$$('[data-lat]').forEach(b=>b.onclick=()=>{pendingSite={lat:Number(b.dataset.lat),lng:Number(b.dataset.lng),name:b.dataset.name};pendingParcel=defaultParcel(pendingSite);pendingPlacement={x:0,z:0,rotation:0};pendingMap();});
$$('[data-map-mode]').forEach(b=>b.onclick=()=>{if(b.dataset.mapMode==='plot'){pendingParcel=[];drawPending();}setMapMode(b.dataset.mapMode);});
$('#clearParcel').onclick=()=>{pendingParcel=defaultParcel(pendingSite);drawPending();setMapMode('building');};
$('#siteRotation').oninput=e=>{pendingPlacement.rotation=Number(e.target.value);drawPending();};
$$('[data-bearing]').forEach(b=>b.onclick=()=>{pendingPlacement.rotation=Number(b.dataset.bearing);drawPending();});
$('#largeMapWrap').onclick=e=>{const rect=e.currentTarget.getBoundingClientRect();const point=screenToGeo(e.clientX-rect.left,e.clientY-rect.top,rect.width,rect.height,pendingSite);if(mapMode==='plot'){if(pendingParcel.length>=12){toast('Up to 12 parcel corners / 地块最多支持 12 个角点');return;}pendingParcel.push(point);drawPending();}else if(mapMode==='building'){const p=toLocal(point,pendingSite);if(pendingParcel.length>=3&&!inPolygon(p,pendingParcel.map(q=>toLocal(q,pendingSite)))){toast('Choose a point inside the drawn parcel. / 请在圈选地块内选择位置。');return;}pendingPlacement={...pendingPlacement,...p};drawPending();}else{pendingSite={...point,name:'Custom site / 自选场地'};pendingParcel=defaultParcel(pendingSite);pendingPlacement={x:0,z:0,rotation:0};pendingMap();}};
$('#siteForm').onsubmit=e=>{e.preventDefault();if(pendingParcel.length<3||!isSimplePolygon(pendingParcel.map(p=>toLocal(p,pendingSite)))){toast('Draw a simple parcel with at least three corners and no crossing edges. / 请圈选至少三个角点，边界不得交叉。');return;}const entered={lat:Number($('#latitude').value),lng:Number($('#longitude').value)};if(entered.lat!==Number(pendingSite.lat.toFixed(6))||entered.lng!==Number(pendingSite.lng.toFixed(6))){pendingParcel=pendingParcel.map(p=>toGeo(toLocal(p,pendingSite),entered));}site={...entered,name:pendingSite.name};parcel=pendingParcel.map(p=>({...p}));placement={...pendingPlacement};$('#rotation').value=placement.rotation;$('#rotationOut').textContent=placement.rotation+'°';$('#siteName').textContent=site.name;updatePosition();loadMiniMap();context=null;$('#contextResult').innerHTML='<span class="status-dot neutral"></span><span>Site updated; refresh context<small>地块与方向已更新，请重新读取周边</small></span>';$('#siteDialog').close();toast('Parcel, position and orientation updated / 已更新地块、建筑位置与朝向');};
async function getJSON(url,options){const response=await fetch(url,options);const data=await response.json();if(!response.ok)throw Error((data.error?.en||'Request failed')+' / '+(data.error?.zh||'请求失败'));return data;}
async function refreshConnections(){try{connections=await getJSON('/api/status');const google=connections.providers.google;$('#apiStatus').innerHTML=google.configured?'Google Maps configured<small>地图服务已配置 · 可查看连接详情</small>':'Offline demonstration<small>内置示例可用 · API 未配置</small>';$('#apiDot').classList.toggle('neutral',!google.configured);}catch{$('#apiStatus').innerHTML='Offline demonstration<small>内置示例可用</small>';$('#apiDot').classList.add('neutral');}}
$('#contextBtn').onclick=async()=>{if(context){showContext();return;}const b=$('#contextBtn');b.disabled=true;$('#contextResult').innerHTML='<span class="spinner" style="width:10px;height:10px"></span><span>Reading surroundings…<small>正在读取真实周边信息…</small></span>';try{context=await getJSON('/api/context',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lat:site.lat,lng:site.lng})});$('#contextResult').innerHTML=`<span class="status-dot"></span><span>${context.places.length} nearby places · ${context.roads.length} road samples<small>Google Maps · 300 m 范围 · 点击查看</small></span>`;showContext();}catch(error){$('#contextResult').innerHTML='<span class="status-dot red"></span><span>Context unavailable; retry<small>周边数据暂不可用，可重试</small></span>';toast(error.message);}finally{b.disabled=false;refreshConnections();}};
function showContext(){const safeUrl=url=>/^https:\/\/(www\.)?(google\.com|maps\.google\.com)\//.test(url??'')?url:null;info('Site context / 场地环境',`<p><b>${context.places.length} nearby places · ${context.roads.length} independently matched road points</b><br><small>300 米范围；道路匹配点不是连续消防通行路径。</small></p>${context.places.slice(0,12).map(p=>`<div class="info-row"><b>${safeUrl(p.url)?`<a href="${escape(p.url)}" target="_blank" rel="noopener">${escape(p.name)} ↗</a>`:escape(p.name)}</b><p>${escape(p.address)}</p>${(p.attributions||[]).map(a=>`<small>${escape(a.provider||a.displayName||'')}</small>`).join('')}</div>`).join('')}<p><small>${escape(context.limitations.en)}<br>${escape(context.limitations.zh)}</small></p><p>Source / 来源：<a href="https://maps.google.com" target="_blank" rel="noopener">Google Maps</a></p><button class="outline" id="refreshContext">Refresh / 重新读取</button>`,'LIVE URBAN CONTEXT · 实时环境信息');$('#refreshContext').onclick=()=>{$('#infoDialog').close();context=null;$('#contextBtn').click();};}
$('#connectionBtn').onclick=()=>{const p=connections?.providers;info('Connections / 接口连接',`<h3>Google Maps Platform</h3><p>${p?.google.configured?'Configured / 已配置':'Not configured / 未配置'}</p><p>Static Maps · Nearby Places · Nearest Roads<br><small>地图、周边地点、独立道路匹配点；不提供实测消防通道尺寸。</small></p><h3>OpenAI · GPT-6.1 Sol</h3><p>${p?.openai.state==='connected'?'Connected / 已连接':p?.openai.configured?'Configured; ready to test / 已配置，可尝试连接':'Not configured / 未配置'}</p><p><small>Rule-based bilingual recommendations work independently. / 仍可使用双语规则建议。</small></p><h3>Credentials / 密钥</h3><p>Kept server-side; never included in exported reviews.<br><small>密钥保存在服务端，不进入浏览器脚本或导出报告。</small></p>`);};
function currentScopeNote(){return caseMode==='garden'?{en:'Four source-object checks in a fictional PG II residential model: three criterion findings and one manually nominated review zone. Applicability, full fire access and remaining codes require separate review.',zh:'针对虚构 PG II 住宅模型开展四项对象审查：三项指标问题及一项人工指定复核区。适用条件、完整消防通行设计及其余规范须另行核对。'}:SCREENING_NOTE;}
function localBrief(){const unresolved=results.filter(r=>r.status!=='pass'&&r.status!=='na');return `<p><b>Rule-based brief / 规则生成建议</b><br><small>Generated from the current checks; no live AI text. / 根据当前检查整理，未使用实时 AI 文本。</small></p>${(unresolved.length?unresolved:results).map((r,i)=>`<div class="info-row"><b>${i+1}. ${escape(r.title.en)} / ${escape(r.title.zh)}</b><p>${escape(r.measured.en)} · ${escape(r.requirement.en)}<br><small>${escape(r.recommendation.en)}<br>${escape(r.recommendation.zh)}</small></p><a href="${SOURCE_URL}" target="_blank" rel="noopener">${escape(r.clause)} ↗</a></div>`).join('')}<p><small>${currentScopeNote().en}<br>${currentScopeNote().zh}</small></p>`;}
$('#aiBtn').onclick=async()=>{const b=$('#aiBtn');b.disabled=true;try{await refreshConnections();if(!connections?.providers.openai.configured||connections.providers.openai.state==='needs-valid-key-or-access'){info('Design brief / 设计建议',localBrief()+'<p><small>Live AI needs a valid API configuration and internet connection. The current brief is rule-based. / 实时 AI 需要有效接口配置及联网，当前展示规则生成建议。</small></p>','SOURCE-LINKED DESIGN ACTIONS');return;}info('Preparing design brief / 正在生成设计建议','<p><span class="spinner" style="display:inline-block;vertical-align:middle;margin-right:10px"></span> Reviewing measurements and source-linked findings…<br><small>正在整理输入参数、检查结果与条款依据…</small></p>','GPT-6.1 · LIVE DESIGN EXPLANATION');const data=await getJSON('/api/explain',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({findings:selectedCode?[...results,{id:selectedCode.id,status:'review',title:selectedCode.title,clause:selectedCode.clause,measured:{en:'Not measured',zh:'未测量'},requirement:selectedCode.requirements,evidence:selectedCode.summary,sourceUrl:selectedCode.sourceUrl,requiredInputs:selectedCode.requiredInputs}]:results,project:{purposeGroup:input.purposeGroup||'unknown',inputSource:input.source,site,model:$('#modelName').textContent}})});info('AI design brief / AI 设计建议',`<div class="brief-text">${escape(data.text)}</div><p><a href="${SOURCE_URL}" target="_blank" rel="noopener">SCDF source / 条款来源 ↗</a></p>${selectedCode?`<p><a href="${escape(selectedCode.sourceUrl)}${selectedCode.page?"#page="+selectedCode.page:""}" target="_blank" rel="noopener">${escape(selectedCode.clause)} · Additional source / 追加依据 ↗</a></p>`:""}`,'GPT-6.1 · LIVE DESIGN EXPLANATION');decorateIssueAnswer({container:$('#infoBody'),textElement:$('#infoBody .brief-text'),answerText:data.text,linkedIssues:data.linkedIssues??results.map(r=>({id:r.id,objectId:r.objectId,status:r.status})),findings:results,onFocusIssue:focusModelIssue});}catch(err){info('Design brief / 设计建议',`<p>${escape(err.message)}</p>`+localBrief());}finally{b.disabled=false;}};
$('#exportBtn').onclick=()=>{const data={project:'SiteCode AI',exportedAt:new Date().toISOString(),scope:currentScopeNote(),geometry:caseMode==='garden'?'user-rhino-model':imported?'imported':'illustrative-sample',model:$('#modelName').textContent,site,placement,parcel:{coordinates:parcel,source:"user-drawn illustrative boundary",area:polygonArea(parcel.map(p=>toLocal(p,site)))},input,findings:results,additionalCode:selectedCode,context:context?{source:'Google Maps',radius:context.radius,nearbyPlaces:context.places,roadSamples:context.roads,limitations:context.limitations}:null};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`SiteCode_Review_${scenario}_${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Bilingual review exported / 已导出中英双语检查记录');};
$('#tourBtn').onclick=()=>info('A 90-second walkthrough / 90 秒演示',`<h3>01 · A design with visible friction<br><small>展示带有空间问题的原始方案</small></h3><p>The office is served by a narrow fire lane, a low canopy and a long dead end. Select the numbered markers to see the measurement and source.<br><small>原始方案有通道过窄、雨棚净空不足和尽端过长等问题。点击编号查看参数与规范依据。</small></p><h3>02 · Put the design in its context<br><small>结合真实场地环境</small></h3><p>Choose a site and read nearby Google Places. Context is real; the architectural scene is illustrative.<br><small>选择位置，读取 Google 周边地点。地图与地点为真实数据，三维建筑与周边体块为演示模型。</small></p><h3>03 · Turn evidence into design action<br><small>把检查依据转化为设计调整</small></h3><p>Apply the proposed changes. The access lane widens, the canopy rises and the dead end shortens. Compare five selected criteria, then export the bilingual review.<br><small>应用调整方案，通道加宽、雨棚抬高、尽端缩短。对比五项指标，并导出双语检查记录。</small></p><p><a href="/assets/FireSite_Office_Sample.3dm" download>↓ Download the sample Rhino model / 下载示例 Rhino 模型</a></p><p><small>These are declared example inputs, with criterion-level screening. / 此为基于申报示例参数的单项筛查。</small></p>`,'FROM CODE TO SPATIAL ACTION');
$$('[data-step]').forEach(b=>b.onclick=()=>{const step=b.dataset.step;$$('[data-step]').forEach(x=>x.classList.toggle('current',x===b));if(step==='model')info('A model made for the demo / 演示模型',`<p>The built-in office is ready to explore. You can also download its Rhino counterpart or import your own geometry.<br><small>内置办公模型已可直接操作，也可下载配套 Rhino 文件或上传自己的模型。</small></p><p><a href="/assets/FireSite_Office_Sample.3dm" download>↓ Download .3dm / 下载 Rhino 模型</a></p><p><small>Sample measurements are declared inputs; uploaded models require measured inputs. / 示例尺寸来自预设参数；上传模型需另行填写测量值。</small></p>`);else if(step==='site')openSite();else if(step==='improve'){if(imported){openParams();return;}setScenario('after');toast('Proposed example loaded / 已切换调整方案');}else{$('#reviewSummary').scrollIntoView({behavior:'smooth',block:'nearest'});}});
const previousTour=$('#tourBtn').onclick;
$('#tourBtn').onclick=()=>{if(caseMode!=='garden'){previousTour();return;}info('A 90-second walkthrough / 90 秒演示',`<h3>01 · Your Rhino model / 展示原始模型</h3><p>Canopy Garden Residences, 20 storeys. Three selected criteria fail and one pool review zone needs confirmation.<br><small>展示 20 层住宅模型，三项指标问题与一项泳池范围复核。</small></p><h3>02 · Select a spatial issue / 点击空间问题</h3><p>Inspect the 2.8 m approach, 3 m pergola clearance and 3 m accessway, with source objects and code links.<br><small>点击标记，查看真实对象、模型尺寸、规范要求和调整建议。</small></p><h3>03 · Search the evidence / 检索规范依据</h3><p>Search 38 local PDFs, select a page and mark a model region.<br><small>搜索 38 份本地规范，查看页码原文并关联模型区域。</small></p><h3>04 · Discuss the design / 与 AI 对话</h3><p>Open the bottom-right GPT-6.1 chat and ask what to revise first.<br><small>打开右下角 AI 对话，询问应优先修改什么。</small></p><p><small>Selected screening criteria and declared project assumptions require confirmation. / 须确认所选筛查条件和项目假设。</small></p>`,'MODEL → CODE → DESIGN ACTION');};
async function loadGardenCase(){
 $('#modelActionPanel')?.remove();$('#sceneLoading').hidden=false;$('#sceneLoading strong').textContent='Loading your Rhino model';
 try{const [reviewResponse,modelResponse]=await Promise.all([fetch('/assets/garden-condo-review.json'),fetch('/assets/garden-condo.glb.gz')]);if(!reviewResponse.ok||!modelResponse.ok)throw Error('Case asset unavailable');gardenReview=await reviewResponse.json();let bytes=new Uint8Array(await modelResponse.arrayBuffer());if(bytes[0]===31&&bytes[1]===139)bytes=new Uint8Array(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer());const meta=await viewer.loadFile(new File([bytes],'garden-condo.glb'),{units:'m'});caseMode='garden';imported=true;input={purposeGroup:'II',habitableHeight:61.145,source:'model-metadata'};scenario='before';selected=gardenReview.findings[0].id;modelDimensions={x:100,z:86};if(!hasSavedDraft())parcel=[[-65,-55],[65,-55],[65,55],[-65,55]].map(([x,z])=>toGeo({x,z},site));$('#rotation').value=placement.rotation;$('#rotationOut').textContent=placement.rotation+'°';$('#modelName').textContent='Canopy Garden Residences';$('#modelSub').textContent='Your .3dm · 20 storeys / 本地20层住宅模型';$('#modelType').textContent='PG II · Residential / 居住';$('.project-name').innerHTML='Canopy Garden Residences <span>／ 原始方案审查</span>';$('.scope-label').textContent='SCDF · PG II residential';$('.scope-note').innerHTML='<span>PG II residential · 20 storeys · 61.145 m declared height<small>居住用途 · 模型声明高度 · 4 项局部审查</small></span>';$('#sceneCaption').innerHTML='YOUR RHINO MODEL <small>本地模型 · 轻量预览</small>';$('#sceneInstruction').innerHTML='Select a marker to review the source object <span>点击标记查看模型对象与依据</span>';$('#provenanceText').innerHTML='Source: garden_condo_before_v01.3dm<small>尺寸来自模型几何与内嵌参数；泳池范围为人工指定的审查区。</small>';$('#sampleBtn').textContent='Reload / 重载';render();updatePosition();return meta;}finally{$('#sceneLoading').hidden=true;}
}
restoreDraft();render();loadMiniMap();refreshConnections();drawParcel();
try{const {createScene}=await import('./scene.js');viewer=await createScene($('#scene'),{onSelectIssue:select,onPlacementChange:p=>{placement={...placement,...p};updatePosition();toast('Model position updated; checks still use declared inputs. / 位置已更新；检查仍依据申报参数。');}});await loadGardenCase();render();updatePosition();$('#sceneLoading').hidden=true;}catch(error){$('#sceneLoading').hidden=true;$('#scene').innerHTML='<div class="scene-error"><strong>3D view could not start / 三维视图未能启动</strong><br>Enable WebGL and reload. The input-based checks remain available.<br>请启用 WebGL 后刷新；参数检查仍可使用。</div>';console.error('Scene initialization failed:',error);}
